import{_ as a,o as d,c as e,a2 as o}from"./chunks/framework.CdvW4CUT.js";const c=JSON.parse('{"title":"常驻 Agent 服务的空闲 CPU 治理：从 16% 到 1.7%，以及三次未达标的迭代","description":"一个常驻 Agent 服务在完全空闲时也持续占用 CPU。通过采样、对照与逐项拆解，把本机应用进程占用从 16% 降到 1.7%，但后续三轮优化并未稳定达到 2–5% 的目标。","frontmatter":{"title":"常驻 Agent 服务的空闲 CPU 治理：从 16% 到 1.7%，以及三次未达标的迭代","date":"2026-11-04T00:00:00.000Z","tags":["性能优化","排查方法","采样","数据库轮询"],"description":"一个常驻 Agent 服务在完全空闲时也持续占用 CPU。通过采样、对照与逐项拆解，把本机应用进程占用从 16% 降到 1.7%，但后续三轮优化并未稳定达到 2–5% 的目标。"},"headers":[],"relativePath":"posts/idle-cpu.md","filePath":"posts/idle-cpu.md"}'),s={name:"posts/idle-cpu.md"};function n(r,t,i,p,l,u){return d(),e("div",null,[...t[0]||(t[0]=[o(`<h1 id="常驻-agent-服务的空闲-cpu-治理-从-16-到-1-7-以及三次未达标的迭代" tabindex="-1">常驻 Agent 服务的空闲 CPU 治理：从 16% 到 1.7%，以及三次未达标的迭代 <a class="header-anchor" href="#常驻-agent-服务的空闲-cpu-治理-从-16-到-1-7-以及三次未达标的迭代" aria-label="Permalink to &quot;常驻 Agent 服务的空闲 CPU 治理：从 16% 到 1.7%，以及三次未达标的迭代&quot;">​</a></h1><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>某金融终端 Agent 平台是&quot;桌面客户端 → 云端协调 API → Agent 执行运行时 → PostgreSQL&quot;的链路，助手实例和数据库同机部署，数据库跑在 Linux 容器里。服务是常驻的，没有任务也一直活着。</p><h2 id="现象" tabindex="-1">现象 <a class="header-anchor" href="#现象" aria-label="Permalink to &quot;现象&quot;">​</a></h2><p>只开着客户端、什么都不做，数据库容器就占 1.47 个核。</p><p>30 秒窗口、8 逻辑处理器：桌面端加后端的 Windows 进程 CPU 合计 16.08%（按 8 逻辑处理器归一，不含容器虚拟机），同一窗口数据库容器原始 CPU 147.24%（100% 约一个逻辑核），事务 373.74 次/秒，新建连接 0.89 次/秒。没有报错，功能也正常，是典型的&quot;默认一直空转&quot;。同事在 Mac 宿主 + Linux 容器上复现，产物已含上一版修复，可以排除&quot;没更新代码&quot;。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>桌面客户端 ──HTTP──&gt; 云端协调 API ──任务/事实──&gt; 执行运行时 ──SQL──&gt; 同机容器 PostgreSQL</span></span>
<span class="line"><span>  ③ 空闲动画                      ① 空队列开事务、每次重新规划</span></span>
<span class="line"><span>     6 条 SVG 动画                ② 就绪自检成功也销毁连接</span></span>
<span class="line"><span>                                  ④ 结构指纹每 5 秒重算</span></span></code></pre></div><h2 id="排查-从假设到证据" tabindex="-1">排查：从假设到证据 <a class="header-anchor" href="#排查-从假设到证据" aria-label="Permalink to &quot;排查：从假设到证据&quot;">​</a></h2><p>先怀疑容器。数据库在容器里，CPU 又记在容器账上，很像配额或参数问题。停掉应用、只留数据库，容器 CPU 中位数 0.86%。这个方向被否定：容器只是负载出现的位置，不是原因。</p><p><strong>假设一：空队列也在开事务。</strong> 读队列工作器源码，25ms 定时器，空结果分支同样开事务、跑完整领取查询。写源码探针：真实定时器跑真实空分支，数据库换成只返回空行的替身。3.002 秒内任务领取 776 次、事实投递 1552 次（默认 4 消费者），合计 2328 次 SQL API 调用，775.4 次/秒，每轮都含 BEGIN/COMMIT。真实 30 秒窗口里，四类领取分别 977、109、460、460 次 calls。</p><p>这里我修正过自己：775 次/秒是 API 调用数，含事务控制，不是 QPS，也不是 CPU。它只能证明&quot;空队列在开事务&quot;这个行为，定量必须上真实实例。这个分工后来成了纪律。</p><p><strong>假设二：就绪自检成功也销毁连接。</strong> 四个角色每轮合计 92 次 SQL API 调用，成功时销毁 4 条连接；空闲窗口新建连接 0.89 次/秒。检查成功也在付建连与认证成本。失败、超时、取消时丢弃是必要的，成功提交后应当归还连接池。</p><p><strong>假设三：修完后端就到底了。</strong> 可逆对照否定了它：同一修复后后端、同一窗口，只暂停或恢复桌面空闲动画，Windows 进程 CPU 从 10.54% 降到 1.11%。Electron 渲染进程 10 秒采样：LayoutCount 1445→136，RecalcStyleCount 1445→181，TaskDuration 2.164→0.283 秒；空页面有 6 条持续 SVG 动画。桌面端是独立热点，量级和后端相当。</p><p><strong>假设四：复用连接会不会带脏事务。</strong> 只在完整事务提交成功且未 abort 时归还，其余一律销毁。只读回归 2 文件 35 项通过；新建连接 0.89→0.10 次/秒（-88.9%）。</p><p><strong>假设五：剩下的是执行还是规划。</strong> 用真实运行时角色做 EXPLAIN 与规划统计：30 秒累计规划 5026.3ms、执行 650.7ms，差一个量级。给两条队列加保守候选预检（先一次廉价存在性判断，没有候选就跳过原事务），预检语句固定命名以复用计划。四类复杂空领取 calls 归零，规划 711.6/724.6ms，执行 614.5/579.6ms，容器 CPU 34.74%→9.20%/9.21%，事务仍约 75 次/秒。事务频率没降，恰好说明领取语义没被削减。</p><p><strong>假设六：结构指纹。</strong> 表结构/约束指纹每 5 秒重算一次。先做只读评估：系统目录查询改成物化子查询或命名语句，没有稳定收益、指纹一致，放弃。再做有界&quot;结构证明&quot;复用：单一检查者、绑定迁移契约与全部账本字段、只在完整事务提交成功后发布、失败/超时/abort/显式刷新/关闭即失效、迟到成功不回填。每类指纹从每 5 秒一次降到 60 秒 3 次（约 -75%）；默认预留与探针预算让实际约 20 秒重验一次。</p><h2 id="根因" tabindex="-1">根因 <a class="header-anchor" href="#根因" aria-label="Permalink to &quot;根因&quot;">​</a></h2><p>不是单点 bug，是四个&quot;空闲也照做&quot;的默认行为叠加：①空队列开事务，且每次重新规划；②就绪自检成功也销毁连接；③桌面空闲动画持续触发布局；④结构指纹每 5 秒重算。前两项是数据库侧主成本，后两项解释了&quot;只修后端&quot;为何仍有残高。</p><h2 id="修复方案与取舍" tabindex="-1">修复方案与取舍 <a class="header-anchor" href="#修复方案与取舍" aria-label="Permalink to &quot;修复方案与取舍&quot;">​</a></h2><p>方案 A（否决）：整体调慢轮询、减少投递消费者、给容器加 CPU 上限。前两个不消除空事务，还牺牲吞吐与取消时延；配额只压最高消耗，让延迟变差。</p><p>方案 B（采用）：分层治理。空闲有界退避 25→50→100→200→250ms，本机提交后即时唤醒；两条队列加保守候选预检；预检与发现语句固定命名；成功提交后归还连接；只保留有限眨眼动画；结构指纹改为最长 30 秒的证明复用。</p><p>代价要写明：控制队列完全空闲可退避到 250ms，跨实例取消最多多约 225ms 轮询等待（另加数据库耗时与基础 tick）；结构证明最长 30 秒有效，管理员手改列或约束的发现会延迟，但普通业务角色没有 DDL 权限。没有采用全量 LISTEN/NOTIFY：写入方覆盖、未来到期、重连补扫与连接预算都没设计好，只当提示又保留 25ms 兜底，控制主项降不下来。</p><h2 id="验证结果" tabindex="-1">验证结果 <a class="header-anchor" href="#验证结果" aria-label="Permalink to &quot;验证结果&quot;">​</a></h2><p>口径：W 是 Windows 宿主指定进程 CPU 时间按 8 逻辑处理器归一，不含 Docker VM；C 是容器原始 CPU，100% 约一个核；T 是事务计数差除以时长；N 是新建连接每秒；P 是累计规划耗时。W 与 C 分母不同，不能相加，也都不是整机总 CPU。</p><table tabindex="0"><thead><tr><th>阶段 / 指标</th><th>修复前</th><th>修复后</th><th>口径与环境</th></tr></thead><tbody><tr><td>第 1 轮 W（桌面＋后端）</td><td>16.08%</td><td>1.73%</td><td>W；30 秒；8 逻辑处理器</td></tr><tr><td>第 1 轮 C</td><td>147.24%</td><td>36.76%</td><td>C；同窗口；约 1.47→0.37 核</td></tr><tr><td>第 1 轮 T / N</td><td>373.74 / 0.89</td><td>81.78 / 0.10</td><td>T、N；同窗口；T 含事务边界</td></tr><tr><td>仅后端 W / C</td><td>2.48% / 136.95%</td><td>0.81% / 34.45%</td><td>W、C；不开桌面端</td></tr><tr><td>新基线复测 W / C / T</td><td>14.20% / 144.60% / 385.35</td><td>2.04% / 43.28% / 84.86</td><td>W、C、T；30 秒；换构建重测，确认可复现</td></tr><tr><td>第 2 轮 C / P</td><td>34.74% / 5026.3ms</td><td>9.20%、9.21% / 711.6、724.6ms</td><td>C、P；30 秒；两个后测窗口独立</td></tr><tr><td>第 3 轮 C</td><td>9.8701%</td><td>7.5476%</td><td>C；120 秒；本窗口 -23.53%</td></tr><tr><td>第 4 轮 C（默认配置）</td><td>7.9164%</td><td>7.7581%</td><td>C；120 秒；约 2% 差异</td></tr><tr><td>第 5 轮 C</td><td>8.2019%</td><td>9.6341% / 6.2805%</td><td>C；120 秒；两窗口均值约 7.96%</td></tr></tbody></table><p>这些数字不代表什么：本机是 Windows 宿主 Node ＋ 同机 Linux 容器 PostgreSQL、8 逻辑处理器，不代表 Mac/ARM，也不代表 macOS 客户端或完整 Linux 应用镜像的部署形态。窗口都是 30 或 120 秒，在回归与构建结束后采集，机器不独占；只证明本机该场景的前后对照，不代表长期容量、活跃积压吞吐或稳定性。第 1 轮、复测与第 2–5 轮是不同时间点的独立对照，数字不可跨组混用。T 含事务边界，不是复杂查询 QPS；P 含等待因素，不能按 CPU 占比分摊。</p><h2 id="复盘" tabindex="-1">复盘 <a class="header-anchor" href="#复盘" aria-label="Permalink to &quot;复盘&quot;">​</a></h2><ol><li>先量再改，把&quot;行为证据&quot;和&quot;成本证据&quot;分开。探针只能告诉我谁在开事务，真实实例才能告诉我贵不贵。此后我一直四组一起看：容器 CPU、事务、新建连接、规划耗时。</li><li>可逆对照比解释有力。只切一个变量（动画、诊断配置），并把偏高的窗口一起留下，比挑最好看的数字更接近真相。</li><li>优化前先列不变量。默认 4 路投递、控制队列独立、5 秒安全检查、锁/租约/取消/ACK/schema 都不动；不变量守住，数字才有解释力。</li></ol><p>没做到的部分：目标是空闲容器 CPU 均值 2–5%，五轮下来第 3–5 轮没有稳定达到。第 3 轮 9.87%→7.55% 是同窗口 -23.53%，仍在目标之上；第 4 轮默认配置只差约 2%；第 5 轮两窗口 9.63%/6.28%、平均约 7.96%，与 8.20% 基线差约 3%，波动大于收益，所以不宣称达标。可压缩的重复规划在前两轮基本吃完（34.74%→9.20%），剩下的是固定控制轮询、就绪自检与跨实例周期发现；继续要走&quot;跨副本通知 + 持久兜底&quot;，那是设计变更，不是调参。Mac/ARM、完整 Linux 镜像、真实供应商、活跃积压与多实例长期稳定性都还没验收；一次渲染层用例超时也没定位，我没有改断言或超时。</p>`,29)])])}const P=a(s,[["render",n]]);export{c as __pageData,P as default};
